"use strict";
function normalizeField(v) {
    if (!v || typeof v !== "object")
        return null;
    const o = v;
    const type = typeof o.type === "string" ? o.type : "";
    const label = typeof o.label === "string" ? o.label : "";
    const key = typeof o.key === "string" ? o.key : "";
    const description = typeof o.description === "string" ? o.description : undefined;
    if (type === "header" || type === "info")
        return label ? { type, label } : null;
    if (!key)
        return null;
    if (type === "text") {
        return {
            type,
            key,
            label: label || key,
            placeholder: typeof o.placeholder === "string" ? o.placeholder : undefined,
            description,
            isPassword: o.isPassword === true || o.secret === true,
            defaultValue: typeof o.defaultValue === "string" ? o.defaultValue : undefined,
        };
    }
    if (type === "select") {
        const options = Array.isArray(o.options)
            ? o.options
                .map((opt) => {
                if (!opt || typeof opt !== "object")
                    return null;
                const r = opt;
                const value = r.value == null ? "" : String(r.value);
                const text = typeof r.label === "string" ? r.label : value;
                return value ? { label: text, value } : null;
            })
                .filter((x) => !!x)
            : [];
        if (!options.length)
            return null;
        return {
            type,
            key,
            label: label || key,
            options,
            defaultValue: o.defaultValue == null ? undefined : String(o.defaultValue),
            description,
        };
    }
    if (type === "toggle" || type === "boolean" || type === "checkbox") {
        return {
            type: "toggle",
            key,
            label: label || key,
            defaultValue: o.defaultValue === true,
            description,
        };
    }
    return null;
}

globalThis.harborNormalizePluginFields = function (json) {
  const raw = JSON.parse(json);
  const list = Array.isArray(raw) ? raw : raw && typeof raw === "object" && Array.isArray(raw.fields) ? raw.fields : [];
  return JSON.stringify(list.map(normalizeField).filter(function (field) { return !!field; }));
};
